class Dreieck
{
  	int seitenlänge;

  	Dreieck()
  	{
      seitenlänge = 3; 
   }

   void gibUmfang()
   {
      println(3 * seitenlänge);
   }

   void gibSeitenlänge() {
      println(seitenlänge);
   }
}

Dreieck d1 = new Dreieck(); 
print("Umfang des Dreiecks ist: ");
d1.gibUmfang();  // Was wird hier ausgegeben? 
println();

println("Seitenlänge des Dreiecks ist: ");
d1.gibSeitenlänge();
